import json, re, sys
def last_boxed(s):
    # find all \boxed{...} with balanced braces, take last
    idxs=[m.start() for m in re.finditer(r'\\boxed\s*\{', s)]
    if not idxs: return None
    i=idxs[-1]
    j=s.index('{', i)
    depth=0
    for k in range(j, len(s)):
        if s[k]=='{': depth+=1
        elif s[k]=='}':
            depth-=1
            if depth==0:
                return s[j+1:k]
    return None
def tonum(x):
    if x is None: return None
    t=x.strip().replace(',','').replace('$','')
    t=re.sub(r'\\text\{([^}]*)\}', r'\1', t)
    t=t.replace('\\%','').replace('%','')
    try:
        return float(t)
