_FRAC_RE = re.compile(r"\\[dt]?frac\s*\{([^{}]*)\}\s*\{([^{}]*)\}")


def _last_boxed(text):
    """Return the content of the last balanced ``\\boxed{...}`` in ``text`` (or None)."""
    start = -1
    search_from = 0
    while True:
        i = text.find("\\boxed", search_from)
        if i < 0:
            break
        j = i + len("\\boxed")
        while j < len(text) and text[j] in " \t":
            j += 1
        if j >= len(text) or text[j] != "{":
            search_from = i + len("\\boxed")
            continue
        depth = 0
        k = j
        while k < len(text):
            if text[k] == "{":
                depth += 1
            elif text[k] == "}":
                depth -= 1
                if depth == 0:
                    break
