                if depth == 0:
                    break
            k += 1
        if depth == 0:
            found = text[j + 1 : k]
        search_from = max(k + 1, j + 1)
    return found


def _to_number(content):
    """Parse a boxed answer as a number; return None when it is not numeric."""
    if content is None:
        return None
    s = content.strip()
    s = s.replace("\\left", "").replace("\\right", "")
    s = _TEXT_RE.sub(" ", s)
    s = s.replace("\\,", "").replace("\\!", "").replace("\\;", "").replace("\\ ", "")
    s = s.replace("$", "").replace("%", "").replace("\\%", "")
    s = s.replace("dfrac", "frac").replace("tfrac", "frac")
    m = _FRAC_RE.search(s)
    if m:
        try:
            den = float(m.group(2).strip())
            if den != 0:
                return float(m.group(1).strip()) / den
        except (TypeError, ValueError):
            return None
    s = s.replace(",", "").strip()
    m = _NUMBER_RE.search(s)
    if not m:
        return None
    try:
        return float(m.group(0).replace(",", ""))
    except ValueError:
        return None


def compute_score(data_source, solution_str, ground_truth, extra_info=None, **kwargs):
    """1.0 iff the number in the response's last ``\\boxed{...}`` equals the gold answer."""
    if not solution_str:
        return 0.0
    pred = _to_number(_last_boxed(solution_str))
    gold = _to_number(str(ground_truth) if ground_truth is not None else None)
    if pred is None or gold is None:
        return 0.0
    return 1.0 if abs(pred - gold) < 1e-6 else 0.0
