import sys,json,re; sys.path.insert(0,'/workspace')
from verl.utils.reward_score.math_verify import compute_score as old
from rewards.math_verify_reward import compute_score as new
def lastbox(o):
    ms=list(re.finditer(r'\\boxed\{([^{}]*)\}',o)); return ms[-1].group(1) if ms else None
def num(x):
    try: return float(str(x).replace(',','').strip().rstrip('.'))
    except Exception: return None
def truth(r):
    b=lastbox(r['output'])
    if b is None: return False
    a=num(b); g=num(r['gts']); return a is not None and g is not None and abs(a-g)<1e-9
def main():
