    fn=[i for i,r in enumerate(rows) if truth(r) and r['score']<0.5]
    vals=[old(rows[i]['output'], rows[i]['gts']) for i in fn]
    print('FN count',len(fn),'old-scorer returns 1.0 on',sum(1 for v in vals if v==1.0))
    for s in [0,50,100]:
        rr=[json.loads(l) for l in open(f'/workspace/results/run100/val_generations/{s}.jsonl')]
        f=[i for i,r in enumerate(rr) if truth(r) and r['score']<0.5]
        print('step',s,'logged false negatives',len(f))
if __name__=='__main__': main()
